'use strict';

const fs = require('node:fs');
const path = require('node:path');
const { pipeline } = require('node:stream/promises');
const { Readable } = require('node:stream');

const {
  DEFAULT_BASE_URL,
  DEFAULT_TIMEOUT_MS,
  DEFAULT_RETRIES,
  PRIMARY_ENDPOINT,
  ENDPOINTS,
} = require('./constants');
const { MediaDownloaderError, ERROR_CODES } = require('./errors');
const { requestOnce } = require('./client');
const { normalize, detectPlatform, isHttpUrl } = require('./normalize');
const { resolveUrl, needsResolve } = require('./resolve');

const BROWSER_UA = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36';

/** Ranking for quality labels so "best" and numeric requests can be compared. */
function qualityScore(label) {
  const text = String(label || '').toLowerCase();

  const pixels = /(\d{3,4})p/.exec(text);
  if (pixels) return Number(pixels[1]);

  // Named tiers used by TikTok and Facebook results.
  if (text.includes('hd_no_watermark')) return 1080;
  if (text.includes('hd')) return 720;
  if (text.includes('no_watermark')) return 540;
  if (text.includes('sd')) return 480;
  if (text.includes('watermark')) return 360;
  if (text.includes('best')) return 9999;

  return 0;
}

/**
 * Pick one media entry.
 * `quality` accepts "best", "worst", or a label such as "360p" / "720p".
 * With no preference, the highest option up to 1080p wins — higher tiers are
 * usually much larger files for little practical gain.
 */
function pickMedia(media, type, quality) {
  const candidates = media.filter((item) => item.type === type);
  if (candidates.length === 0) return null;
  if (candidates.length === 1) return candidates[0];

  const ranked = [...candidates].sort((a, b) => qualityScore(b.quality) - qualityScore(a.quality));

  if (!quality) {
    return ranked.find((item) => qualityScore(item.quality) <= 1080) || ranked[0];
  }

  const wanted = String(quality).toLowerCase();
  if (wanted === 'best') return ranked[0];
  if (wanted === 'worst') return ranked[ranked.length - 1];

  const exact = candidates.find((item) => String(item.quality || '').toLowerCase().includes(wanted));
  if (exact) return exact;

  const target = qualityScore(wanted);
  if (target > 0) {
    // Closest available tier to what was asked for.
    return ranked.reduce((best, item) =>
      Math.abs(qualityScore(item.quality) - target) < Math.abs(qualityScore(best.quality) - target)
        ? item
        : best
    );
  }

  return ranked[0];
}

/** Client for api.satoru.click. */
class MediaDownloader {
  /**
   * @param {object} [options]
   * @param {string} [options.baseUrl] Point at your own deployment if needed.
   * @param {number} [options.timeout] Per-request timeout in ms.
   * @param {number} [options.retries] Retry count for transient failures.
   * @param {string} [options.endpoint] Override the endpoint every call uses.
   */
  constructor(options = {}) {
    this.baseUrl = options.baseUrl || DEFAULT_BASE_URL;
    this.timeout = options.timeout ?? DEFAULT_TIMEOUT_MS;
    this.retries = options.retries ?? DEFAULT_RETRIES;
    this.endpoint = options.endpoint || PRIMARY_ENDPOINT;
    this.headers = options.headers || {};
    this.userAgent = options.userAgent;
    this.lastRateLimit = null;
  }

  /** Every endpoint this client knows how to call. */
  static get endpoints() {
    return Object.keys(ENDPOINTS);
  }

  /** The endpoint used unless overridden. */
  static get primaryEndpoint() {
    return PRIMARY_ENDPOINT;
  }

  /** Label the platform for a URL. */
  static detect(url) {
    return detectPlatform(url);
  }

  _assertUrl(url) {
    if (!isHttpUrl(url)) {
      throw new MediaDownloaderError('URL must start with http:// or https://', {
        code: ERROR_CODES.INVALID_URL,
      });
    }
  }

  /**
   * Fetch media info. Any http(s) URL is accepted — everything goes through
   * the same endpoint.
   *
   * @param {string} url
   * @param {object} [options]
   * @param {string} [options.quality] "best" | "worst" | "360p" | "720p" | ...
   * @param {string} [options.endpoint] Use a different endpoint for this call.
   * @param {boolean} [options.resolve] Eagerly resolve progress-stream links.
   * @param {(p: {percent: number, status: string}) => void} [options.onProgress]
   * @returns {Promise<object>}
   */
  async download(url, options = {}) {
    this._assertUrl(url);

    const endpoint = options.endpoint || this.endpoint;

    const { body, rateLimit } = await requestOnce(this.baseUrl, endpoint, url, {
      timeoutMs: this.timeout,
      retries: this.retries,
      headers: this.headers,
      userAgent: this.userAgent,
      params: this._toParams(endpoint, options),
    });

    if (rateLimit) this.lastRateLimit = rateLimit;

    const result = normalize(body, { sourceUrl: url, endpoint });

    if (!result.ok) {
      throw new MediaDownloaderError('No media found in the response', {
        code: ERROR_CODES.NO_MEDIA,
        endpoint,
      });
    }

    // Attach the picks for the requested quality.
    const video = pickMedia(result.media, 'video', options.quality);
    const audio = pickMedia(result.media, 'audio', options.quality);

    result.video = video ? video.url : null;
    result.audio = audio ? audio.url : null;
    result.videoQuality = video ? video.quality || null : null;
    result.pending = result.media.some((item) => item.pending);

    if (options.resolve) {
      // Each resolve waits on server-side encoding (~25s), so only do the ones asked for.
      const wanted = options.resolveType || 'both';

      if (video && video.pending && wanted !== 'audio') {
        const resolved = await resolveUrl(video.url, { onProgress: options.onProgress });
        result.video = resolved.url;
        if (resolved.duration != null) result.duration = resolved.duration;
      }

      if (audio && audio.pending && wanted !== 'video') {
        const resolved = await resolveUrl(audio.url, { onProgress: options.onProgress });
        result.audio = resolved.url;
      }

      result.pending = [result.video, result.audio].some((link) => needsResolve(link));
    }

    return result;
  }

  /** Call a specific endpoint, bypassing the default. */
  async fromEndpoint(endpoint, url, params = {}) {
    return this.download(url, { ...params, endpoint });
  }

  /** Map friendly options onto each endpoint's real params. */
  _toParams(endpoint, options) {
    const params = {};

    if (endpoint === 'downallv4') {
      if (options.quality) params.quality = options.quality;
      if (options.audio === false) params.music = 'false';
    }

    if (endpoint === 'youtubedl') {
      // This package always returns links, never base64 blobs.
      params.base64 = 'false';
      if (options.format) params.format = options.format;
    }

    if (endpoint === 'sp-dl' && options.quality) params.quality = options.quality;
    if (endpoint === 'bilibili-download' && options.cookies) params.cookies = options.cookies;

    return params;
  }

  /** Get a ready-to-use video link, resolving a progress stream if needed. */
  async videoUrl(url, options = {}) {
    const result = await this.download(url, { ...options, resolve: true, resolveType: 'video' });
    return result.video;
  }

  /** Get a ready-to-use audio link, resolving a progress stream if needed. */
  async audioUrl(url, options = {}) {
    const result = await this.download(url, { ...options, resolve: true, resolveType: 'audio' });
    return result.audio;
  }

  /**
   * Download the file to disk.
   *
   * @param {string} url Original page URL, not a CDN link.
   * @param {string} destination File path, or a directory when it ends in a slash.
   * @param {object} [options]
   * @param {'video'|'audio'} [options.type] Defaults to video.
   * @returns {Promise<{path: string, bytes: number, sourceUrl: string, mediaUrl: string}>}
   */
  async save(url, destination, options = {}) {
    const type = options.type === 'audio' ? 'audio' : 'video';

    // Only resolve the track being saved; each resolve waits on server encoding.
    const result = await this.download(url, { ...options, resolve: true, resolveType: type });

    const mediaUrl = type === 'audio' ? result.audio : result.video;

    if (!mediaUrl) {
      throw new MediaDownloaderError(`No ${type} link available for this URL`, {
        code: ERROR_CODES.NO_MEDIA,
        endpoint: result.endpoint,
      });
    }

    const target = /[\\/]$/.test(destination)
      ? path.join(destination, this._suggestName(result, type))
      : destination;

    const directory = path.dirname(target);
    if (directory && directory !== '.') fs.mkdirSync(directory, { recursive: true });

    const response = await fetch(mediaUrl, {
      headers: { 'User-Agent': this.userAgent || BROWSER_UA },
      signal: AbortSignal.timeout(Math.max(this.timeout, 300000)),
    });

    if (!response.ok || !response.body) {
      throw new MediaDownloaderError(`Download failed: HTTP ${response.status}`, {
        code: ERROR_CODES.UPSTREAM,
        status: response.status,
      });
    }

    await pipeline(Readable.fromWeb(response.body), fs.createWriteStream(target));

    return {
      path: target,
      bytes: fs.statSync(target).size,
      sourceUrl: url,
      mediaUrl,
    };
  }

  /** Build a filename from the title, stripped of characters Windows rejects. */
  _suggestName(result, type) {
    const base = (result.title || result.platform || 'media')
      .replace(/[<>:"/\\|?*\x00-\x1f]/g, '_')
      .replace(/\s+/g, ' ')
      .trim()
      .slice(0, 80) || 'media';

    return `${base}.${type === 'audio' ? 'mp3' : 'mp4'}`;
  }
}

const shared = new MediaDownloader();

/** Fetch media info with default settings. */
const download = (url, options) => shared.download(url, options);

/** Call a specific endpoint with default settings. */
const fromEndpoint = (endpoint, url, params) => shared.fromEndpoint(endpoint, url, params);

/** Download to disk with default settings. */
const save = (url, destination, options) => shared.save(url, destination, options);

module.exports = {
  MediaDownloader,
  download,
  fromEndpoint,
  save,
  detectPlatform,
  resolveUrl,
  needsResolve,
  pickMedia,
  qualityScore,
  MediaDownloaderError,
  ERROR_CODES,
  endpoints: MediaDownloader.endpoints,
  PRIMARY_ENDPOINT,
  API_BASE_URL: DEFAULT_BASE_URL,
};
